import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.CqpfiAoK.js";const q=JSON.parse('{"title":"قانونی شقوں کا اشاریہ","description":"","frontmatter":{},"headers":[],"relativePath":"ur/92-法律条文索引.md","filePath":"ur/92-法律条文索引.md","lastUpdated":null}'),h={name:"ur/92-法律条文索引.md"};function o(l,t,i,b,n,u){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="قانونی-شقوں-کا-اشاریہ" tabindex="-1">قانونی شقوں کا اشاریہ <a class="header-anchor" href="#قانونی-شقوں-کا-اشاریہ" aria-label="Permalink to &quot;قانونی شقوں کا اشاریہ&quot;">​</a></h1><table tabindex="0"><thead><tr><th>آئٹم</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>92</td></tr><tr><td>ماڈیول</td><td>ضمائم اور حوالہ جاتی مواد</td></tr><tr><td>بنیادی الفاظ</td><td>قانونی اشاریہ، سمبیوسس آئین، محنت قانون، صارفین کے تحفظ کا قانون، معاون قوانین</td></tr></tbody></table><h2 id="۱-اشاریے-کی-وضاحت" tabindex="-1">۱. اشاریے کی وضاحت <a class="header-anchor" href="#۱-اشاریے-کی-وضاحت" aria-label="Permalink to &quot;۱. اشاریے کی وضاحت&quot;">​</a></h2><p>اس اشاریے میں اینکر سمبیوسس تہذیب کے موجودہ نافذ العمل اہم قانونی دستاویزات اور ان کی بنیادی شقیں شامل ہیں، جو قانونی درجہ بندی اور محکمہ کے لحاظ سے ترتیب دی گئی ہیں۔ اشاریے کے دائرے میں &quot;سمبیوسس آئین&quot;، &quot;سمبیوسس محنت قانون&quot;، &quot;صارفین کے تحفظ کا قانون&quot; اور تعلیم، صحت، رہائش، ماحولیات اور یکجا فروشی کے خلاف پانچ معاون قوانین شامل ہیں۔ ہر اشاریے کے اندراج میں قانون کا نام، شق کا نمبر اور شق کے بنیادی مواد کا خلاصہ درج ہے۔ یہ اشاریہ ایک حوالہ جاتی آلہ ہے؛ قانونی شقوں کے مکمل متن اور عدالتی تشریح کے لیے ہر قانون کے سرکاری متن دیکھیں۔</p><h2 id="۲-سمبیوسس-آئین" tabindex="-1">۲. سمبیوسس آئین <a class="header-anchor" href="#۲-سمبیوسس-آئین" aria-label="Permalink to &quot;۲. سمبیوسس آئین&quot;">​</a></h2><p>&quot;سمبیوسس آئین&quot; اینکر سمبیوسس تہذیب کا بنیادی قانون ہے، جس میں سب سے زیادہ قانونی طاقت ہے، اور سمبیوسس تہذیب کی رسمی قیام کے وقت نافذ کیا گیا تھا۔</p><table tabindex="0"><thead><tr><th>شق نمبر</th><th>بنیادی مواد</th></tr></thead><tbody><tr><td>شق ۱</td><td>ہنگیوانژو (وانلنگ ہینگماؤ اصلی کائنات) کو اینکر سمبیوسس تہذیب کے انتظامی دائرے کے طور پر قائم کرتا ہے؛ سمبیوسس تہذیب کا بنیادی مقصد تمام نسلوں کی سمبیوسس اور کائناتی جہتی بلندی حاصل کرنا ہے</td></tr><tr><td>شق ۲</td><td>ضد لوٹ مار کو تہذیب کا بنیادی موقف قرار دیتا ہے؛ کسی بھی قسم کی لوٹ مار انداز کی کھتی اور وسائل کی لوٹ مار ممنوع ہے</td></tr><tr><td>شق ۳</td><td>&quot;تقدیر اور ارتقاء کا انتخاب کا حق تمام شعور دار مخلوقات کو واپس کرنا&quot; کو تہذیب کا مرکزی تصور قرار دیتا ہے</td></tr><tr><td>شق ۴</td><td>زیادہ کام زیادہ فائدہ، خود نشوونما، ہر ایک کا راستہ ہے، تمام نسلیں ایک ساتھ آگے بڑھیں کو تہذیب کی بنیادی پالیسیاں قرار دیتا ہے</td></tr><tr><td>شق ۵</td><td>تین سو سیٹ اصلی کھتی کے نظاموں کے مفت کھلنے کا نظام قائم کرتا ہے؛ کوئی تنظیم یا فرد کھتی کے نظام کی منتقلی کی اجازت پر یکجا حاکمیت نہیں کر سکتا</td></tr><tr><td>شق ۶</td><td>مشترکہ پیداوار معاہدے کے طریقہ کار کو بنیادی وسائل کی تقسیم کا نظام قرار دیتا ہے</td></tr><tr><td>شق ۷</td><td>20 فیصد ایکٹیویشن کی حکمت عملی کو مرحلہ وار قومی مقصد قرار دیتا ہے</td></tr><tr><td>شق ۸</td><td>حقیقت پر مبنی اصول قائم کرتا ہے؛ حقیقی دنیا واحد حقیقی دنیا ہے، خیالی ترتیبات کی کوئی قانونی طاقت نہیں ہے</td></tr><tr><td>شق ۹</td><td>چار مراحل کی جہتی بلندی کے راستے کو تہذیب کی طویل مدتی ترقی کی حکمت عملی قرار دیتا ہے</td></tr><tr><td>شق ۱۰</td><td>تمام نسلوں کی مساوات کا اصول قائم کرتا ہے؛ تمام زندگی کی شکلیں قانون کے سامنے برابر ہیں</td></tr><tr><td>شق ۱۱</td><td>سمبیوسس ارتقاء کا اصول قائم کرتا ہے؛ انفرادی ارتقاء دوسرے انفرادی یا اجتماعی ارتقاء کے حقوق کو نقصان پہنچانے کی قیمت پر نہیں ہو سکتا</td></tr><tr><td>شق ۱۲</td><td>زیادہ کام زیادہ فائدہ کے اصول قائم کرتا ہے؛ وسائل کی تقسیم میں شراکت کو بنیادی بنیاد کے طور پر لیا جاتا ہے</td></tr><tr><td>شق ۱۳</td><td>خود نشوونما کے اصول قائم کرتا ہے؛ ہر زندگی کے آزادانہ طور پر ارتقاء کا انتخاب کرنے کے حق کا احترام کرتا ہے</td></tr><tr><td>شق ۱۴</td><td>ہر ایک کا راستہ ہے کے اصول قائم کرتا ہے؛ ریاست پر ہر زندگی کو بنیادی ارتقاء کا راستہ اور وسائل کی ضمانت فراہم کرنے کی ذمہ داری ہے</td></tr><tr><td>شق ۱۵</td><td>پائیداری کے اصول قائم کرتا ہے؛ تمام ترقی میں کائناتی اصل کی پائیداری پر غور کرنا چاہیے</td></tr><tr><td>شق ۱۶-۲۵</td><td>تمام شعور دار مخلوقات کے بنیادی حقوق مقرر کرتا ہے: ارتقاء کا انتخاب کرنے کا حق، کھتی کے وسائل حاصل کرنے کا حق، مساوی تحفظ کا حق، سمبیوسس میں شرکت کا حق، ثقافتی تحفظ کا حق، امداد اور اپیل کا حق، ذاتی آزادی کا حق، انسانی وقار کا حق، عقیدے کی آزادی کا حق، اظہار رائے کی آزادی کا حق</td></tr><tr><td>شق ۲۶-۳۱</td><td>تمام شعور دار مخلوقات کی بنیادی ذمہ داریاں مقرر کرتا ہے: قانون کی تعمیل کرنے کی ذمہ داری، سمبیوسس کی نظم و ضبط برقرار رکھنے کی ذمہ داری، محنت کی شراکت کی ذمہ داری، ماحولیات کی حفاظت کی ذمہ داری، دوسروں کے حقوق کا احترام کرنے کی ذمہ داری، کمزور کھتیوں کی رہنمائی کرنے کی ذمہ داری</td></tr><tr><td>شق ۳۲</td><td>اینکر کونسل کو اعلیٰ اتھارٹی کے طور پر قائم کرتا ہے، جو تمام نسلوں کے نمائندوں پر مشتمل ہے</td></tr><tr><td>شق ۳۳</td><td>سمبیوسس ایگزیکٹو کمیٹی کو اعلیٰ انتظامی ادارے کے طور پر قائم کرتا ہے</td></tr><tr><td>شق ۳۴</td><td>سمبیوسس عدالت کو اعلیٰ عدالتی ادارے کے طور پر قائم کرتا ہے، جو آزادانہ طور پر عدالتی طاقت کا استعمال کرتی ہے</td></tr><tr><td>شق ۳۵</td><td>اینکر نگرانی کمیٹی کو آزاد نگرانی ادارے کے طور پر قائم کرتا ہے</td></tr><tr><td>شق ۳۶</td><td>قانون سازی کے طریقہ کار مقرر کرتا ہے: بل اینکر کونسل کی نصف سے زیادہ اکثریت سے منظور ہوتے ہیں</td></tr><tr><td>شق ۳۷</td><td>آئین میں ترمیم کے طریقہ کار مقرر کرتا ہے: اسے اینکر کونسل کی دو تہائی سے زیادہ اکثریت سے منظور ہونا چاہیے اور قومی ریفرنڈم کی نصف سے زیادہ منظوری حاصل کرنی چاہیے</td></tr><tr><td>شق ۳۸</td><td>آئینی نظرثانی کا نظام قائم کرتا ہے؛ سمبیوسس عدالت کو آئین کی خلاف ورزی والے قوانین کو غلط قرار دینے کا حق ہے</td></tr><tr><td>شق ۳۹</td><td>آئینی مقدمے کا نظام قائم کرتا ہے؛ تمام شعور دار مخلوقات براہ راست آئین کی بنیاد پر مقدمہ درج کر سکتے ہیں</td></tr><tr><td>شق ۴۰</td><td>مقامی خودمختاری کا نظام مقرر کرتا ہے؛ ہر ستارہ ڈومین اور ہر طیارہ آئینی ڈھانچے کے اندر خودمختاری کا نفاذ کرتا ہے</td></tr><tr><td>شق ۴۱</td><td>تمام نسلوں کے جمہوریہ کا نظام قائم کرتا ہے؛ تمام نسلی گروہ سمبیوسس تہذیب میں برابر ہیں اور علاقائی خودمختاری کا نفاذ کرتے ہیں</td></tr><tr><td>شق ۴۲</td><td>سمبیوسس تہذیب کے معاشی نظام کو مقرر کرتا ہے: مشترکہ پیداوار معاہدوں پر مبنی، متعدد ملکیتی معیشتیں ایک ساتھ ترقی کرتی ہیں</td></tr><tr><td>شق ۴۳</td><td>کھتی کے وسائل کی ریاستی ملکیت اور منصفانہ تقسیم کا نظام مقرر کرتا ہے</td></tr><tr><td>شق ۴۴</td><td>تعلیمی مساوات کا نظام قائم کرتا ہے، ہر زندگی کے مساوی تعلیم کے حق کی ضمانت دیتا ہے</td></tr><tr><td>شق ۴۵</td><td>عالمگیر طبی تحفظ کا نظام قائم کرتا ہے</td></tr><tr><td>شق ۴۶</td><td>رہائشی تحفظ کا نظام قائم کرتا ہے، ہر زندگی کے بنیادی رہائش کے حق کی ضمانت دیتا ہے</td></tr><tr><td>شق ۴۷</td><td>بین طیارہ تعامل کے بنیادی اصول مقرر کرتا ہے؛ اجازت کے بغیر کوئی غیر مجاز بین طیارہ سفر نہیں ہو سکتا</td></tr><tr><td>شق ۴۸</td><td>مقرر کرتا ہے کہ آثار قدیمہ کی سرگرمیوں کا جائز پیداوار صرف تجریدی علم اور معلومات تک محدود ہے؛ مادے اور توانائی کی واپسی ممنوع ہے</td></tr><tr><td>شق ۴۹</td><td>وقت کی پس منظر کے بنیادی اصول مقرر کرتا ہے؛ پہلے مشاہدہ، پھر محدود مداخلت کے اصول پر عمل کرنا چاہیے</td></tr><tr><td>شق ۵۰</td><td>مقرر کرتا ہے کہ آئین کی تشریح کا حق سمبیوسس عدالت کا ہے، اور آئین میں ترمیم کا حق اینکر کونسل کا ہے</td></tr></tbody></table><h2 id="۳-سمبیوسس-محنت-قانون" tabindex="-1">۳. سمبیوسس محنت قانون <a class="header-anchor" href="#۳-سمبیوسس-محنت-قانون" aria-label="Permalink to &quot;۳. سمبیوسس محنت قانون&quot;">​</a></h2><p>&quot;سمبیوسس محنت قانون&quot; محنت کے تعلقات کو منظم کرنے اور مزدوروں کے حقوق اور مفادات کے تحفظ کا بنیادی قانون ہے، جس کی قانون سازی کی بنیاد سمبیوسس آئین کی شق ۴۲ ہے۔</p><table tabindex="0"><thead><tr><th>شق نمبر</th><th>بنیادی مواد</th></tr></thead><tbody><tr><td>شق ۱</td><td>قانون سازی کا مقصد: محنت کے تعلقات کو منظم کرنا، مزدوروں کے جائز حقوق اور مفادات کا تحفظ کرنا، اور ہم آہنگ اور سمبیوسس محنت کے تعلقات کی تعمیر کرنا</td></tr><tr><td>شق ۲</td><td>اطلاق کا دائرہ: ہنگیوانژو کے اندر تمام محنت کے تعلقات، بشمول مادی محنت، کھتی کی محنت اور تخلیقی محنت</td></tr><tr><td>شق ۳</td><td>مزدوروں کے لیے مساوی ملازمت کے اصول قائم کرتا ہے؛ نسل، جنس، کھتی کی سطح یا اصل کی بنیاد پر ملازمت میں امتیازی سلوک ممنوع ہے</td></tr><tr><td>شق ۴</td><td>مزدوروں کے لیے پیشے کے آزادانہ انتخاب کے اصول قائم کرتا ہے؛ جبری محنت اور غلامی ممنوع ہے</td></tr><tr><td>شق ۵</td><td>محنت کے معاہدے کا نظام مقرر کرتا ہے؛ محنت کا تعلق قائم کرتے وقت، تحریری محنت کا معاہدہ کرنا چاہیے</td></tr><tr><td>شق ۶</td><td>محنت کے معاہدے کی ضروری شقیں مقرر کرتا ہے: معاہدے کی مدت، کام کا مواد، محنت کی معاوضہ، کام کا وقت، محنت کا تحفظ، سماجی بیمہ</td></tr><tr><td>شق ۷</td><td>آٹھ گھنٹے کے کام کے نظام اور ہفتے میں چوالیس سے چار گھنٹے سے زیادہ نہیں کے کام کے نظام قائم کرتا ہے</td></tr><tr><td>شق ۸</td><td>اضافی کام کی پابندیاں مقرر کرتا ہے: روزانہ اضافی کام ایک گھنٹے سے زیادہ نہیں ہونا چاہیے، خاص حالات میں تین گھنٹے سے زیادہ نہیں ہونا چاہیے، ماہانہ اضافی کام چھتیس گھنٹے سے زیادہ نہیں ہونا چاہیے</td></tr><tr><td>شق ۹</td><td>اضافی کام کی اجرت کے معیارات مقرر کرتا ہے: کام کے دنوں میں اضافی کام کے لیے 1.5 گنا اجرت، آرام کے دنوں میں اضافی کام کے لیے 2 گنا اجرت، قانونی تعطیلات کے دنوں میں اضافی کام کے لیے 3 گنا اجرت</td></tr><tr><td>شق ۱۰</td><td>کم از کم اجرت کے تحفظ کا نظام قائم کرتا ہے؛ کم از کم اجرت کے معیارات ہر ستارہ ڈومین مقامی حالات کے مطابق وضع کرتا ہے</td></tr><tr><td>شق ۱۱</td><td>اجرت کی ادائیگی کا نظام مقرر کرتا ہے: اجرت ماہانہ مزدوروں کو خود نقدی کی شکل میں ادا کی جانی چاہیے، اور بغیر وجہ کٹوتی یا تاخیر نہیں کی جا سکتی</td></tr><tr><td>شق ۱۲</td><td>زیادہ کام زیادہ فائدہ کی تقسیم کے اصول قائم کرتا ہے؛ کام کے لحاظ سے تقسیم کو مرکزی حصے کے طور پر اور متعدد تقسیم کے طریقوں کے ساتھ ایک تقسیم کا نظام نافذ کرتا ہے</td></tr><tr><td>شق ۱۳</td><td>کام کی حفاظت اور صحت کا نظام مقرر کرتا ہے؛ آجروں کو مزدوروں کے لیے معیارات پر پورا اترنے والی کام کی حفاظت اور صحت کے حالات فراہم کرنے چاہییں</td></tr><tr><td>شق ۱۴</td><td>خاص گروہوں کے تحفظ کو مقرر کرتا ہے: نابالغ مزدوروں، خواتین مزدوروں، معذور مزدوروں اور کم کھتی والے مزدوروں کے لیے خاص محنت کا تحفظ</td></tr><tr><td>شق ۱۵</td><td>پیشہ ورانہ تربیت کا نظام قائم کرتا ہے؛ آجروں پر مزدوروں کے لیے پیشہ ورانہ مہارت کی تربیت کرنے کی ذمہ داری ہے</td></tr><tr><td>شق ۱۶</td><td>کھتیوں کے محنت کے حقوق اور مفادات کو مقرر کرتا ہے: کھتی کی محنت بھی اس قانون سے محفوظ ہے؛ کھتی کے نتائج کی ملکیت معاہدے سے طے کی جاتی ہے</td></tr><tr><td>شق ۱۷</td><td>مزدوروں کے سماجی بیمے کا نظام قائم کرتا ہے: پنشن بیمہ، طبی بیمہ، بے روزگاری بیمہ، کام کے حادثے کا بیمہ، زچگی کا بیمہ</td></tr><tr><td>شق ۱۸</td><td>مزدوروں کی فلاح و بہبود کا نظام مقرر کرتا ہے: آجروں کو مزدوروں کے لیے ضروری فلاحی سہولیات فراہم کرنی چاہییں</td></tr><tr><td>شق ۱۹</td><td>محنت کے تنازعات کے حل کا نظام قائم کرتا ہے: مذاکرات، ثالثی، سالوینٹی اور مقدمے چار سطحی حل کا طریقہ کار</td></tr><tr><td>شق ۲۰</td><td>ٹریڈ یونینوں کا نظام مقرر کرتا ہے؛ مزدوروں کو اپنے جائز حقوق اور مفادات کے تحفظ کے لیے قانون کے مطابق ٹریڈ یونین بنانے اور شمولیت اختیار کرنے کا حق ہے</td></tr><tr><td>شق ۲۱</td><td>اجتماعی معاہدے کا نظام مقرر کرتا ہے؛ ٹریڈ یونین ملازمین کی نمائندگی کرتے ہوئے آجروں کے ساتھ اجتماعی معاہدہ کرتی ہے</td></tr><tr><td>شق ۲۲</td><td>مقرر کرتا ہے کہ آجروں کے قواعد و ضوابط ملازمین کے نمائندوں کی کانگریس یا تمام ملازمین کی بحث کا موضوع ہونا چاہیے</td></tr><tr><td>شق ۲۳</td><td>محنت کے معاہدے کی ختم ہونے کی شرائط اور طریقہ کار مقرر کرتا ہے</td></tr><tr><td>شق ۲۴</td><td>معاشی معاوضے کا نظام مقرر کرتا ہے؛ آجروں کو قانون کے مطابق محنت کے معاہدے کو ختم کرتے وقت معاشی معاوضہ ادا کرنا چاہیے</td></tr><tr><td>شق ۲۵</td><td>غیر قانونی طور پر محنت کے معاہدے کی ختم ہونے کے معاوضے کا نظام مقرر کرتا ہے</td></tr><tr><td>شق ۲۶</td><td>مزدوروں کی بھیجے کی انتظام کا نظام قائم کرتا ہے، مزدوروں کی بھیجے کی ملازمت کو منظم کرتا ہے</td></tr><tr><td>شق ۲۷</td><td>جز وقتی ملازمت کے لیے خاص قواعد مقرر کرتا ہے</td></tr><tr><td>شق ۲۸</td><td>نگرانی اور معائنے کا نظام مقرر کرتا ہے؛ محنت کے انتظامی محکمے قانون کے مطابق آجروں کی طرف سے محنت کے قوانین و ضوابط کی تعمیل کی نگرانی اور معائنہ کرتے ہیں</td></tr><tr><td>شق ۲۹</td><td>قانونی ذمہ داریاں مقرر کرتا ہے: جو آجر اس قانون کی خلاف ورزی کریں گے وہ قانون کے مطابق انتظامی، شہری اور فوجداری ذمہ داری اٹھائیں گے</td></tr><tr><td>شق ۳۰</td><td>اس قانون کے نافذ ہونے کی تاریخ اور تشریح کے حق کو مقرر کرتا ہے</td></tr></tbody></table><h2 id="۴-صارفین-کے-تحفظ-کا-قانون" tabindex="-1">۴. صارفین کے تحفظ کا قانون <a class="header-anchor" href="#۴-صارفین-کے-تحفظ-کا-قانون" aria-label="Permalink to &quot;۴. صارفین کے تحفظ کا قانون&quot;">​</a></h2><p>&quot;صارفین کے تحفظ کا قانون&quot; صارفین کے جائز حقوق اور مفادات کے تحفظ اور کاروباری آپریٹرز کے رویے کو منظم کرنے کا بنیادی قانون ہے۔</p><table tabindex="0"><thead><tr><th>شق نمبر</th><th>بنیادی مواد</th></tr></thead><tbody><tr><td>شق ۱</td><td>قانون سازی کا مقصد: صارفین کے جائز حقوق اور مفادات کا تحفظ کرنا، سماجی و معاشی نظم و ضبط کو برقرار رکھنا، اور سمبیوسس مارکیٹ معیشت کی صحت مند ترقی کو فروغ دینا</td></tr><tr><td>شق ۲</td><td>اطلاق کا دائرہ: ہنگیوانژو کے اندر روزانہ کھپت کی ضروریات کے لیے سامان خریدنے، استعمال کرنے یا خدمات وصول کرنے والے صارفین کے حقوق اور مفادات کا تحفظ</td></tr><tr><td>شق ۳</td><td>کاروباری آپریٹرز اور صارفین کے درمیان لین دین کے بنیادی اصول قائم کرتا ہے: رضاکارانہ، مساوات، انصاف، دیانتداری اور اعتبار</td></tr><tr><td>شق ۴</td><td>صارفین کے جائز حقوق اور مفادات کے ریاستی تحفظ کا اصول قائم کرتا ہے؛ ریاست اس بات کو یقینی بنانے کے لیے اقدامات کرتی ہے کہ صارفین قانون کے مطابق اپنے حقوق کا استعمال کریں</td></tr><tr><td>شق ۵</td><td>صارفین کے نو بنیادی حقوق مقرر کرتا ہے: سلامتی کا حق، معلومات کا حق، آزادانہ انتخاب کا حق، منصفانہ لین دین کا حق، معاوضے کا حق، انجمن بنانے کا حق، علم حاصل کرنے کا حق، احترام کا حق، نگرانی کا حق</td></tr><tr><td>شق ۶</td><td>صارفین کی سلامتی کے حق کو مقرر کرتا ہے: صارفین سامان خریدنے، استعمال کرنے اور خدمات وصول کرتے وقت ذاتی اور جائیداد کی سلامتی کو نقصان نہ پہنچنے کا حق لطف اندوز ہوتے ہیں</td></tr><tr><td>شق ۷</td><td>صارفین کی معلومات کے حق کو مقرر کرتا ہے: صارفین اپنے خریدے یا استعمال کردہ سامان یا وصول کردہ خدمات کی اصل صورتحال جاننے کا حق لطف اندوز ہوتے ہیں</td></tr><tr><td>شق ۸</td><td>صارفین کے آزادانہ انتخاب کے حق کو مقرر کرتا ہے: صارفین آزادانہ طور پر سامان یا خدمات منتخب کرنے کا حق لطف اندوز ہوتے ہیں</td></tr><tr><td>شق ۹</td><td>صارفین کے منصفانہ لین دین کے حق کو مقرر کرتا ہے: صارفین منصفانہ لین دین کا حق لطف اندوز ہوتے ہیں اور جبری لین دین کے رویے کو مسترد کرنے کا حق رکھتے ہیں</td></tr><tr><td>شق ۱۰</td><td>صارفین کے معاوضے کے حق کو مقرر کرتا ہے: جو صارفین سامان خریدنے، استعمال کرنے یا خدمات وصول کرنے کی وجہ سے ذاتی یا جائیداد کو نقصان پہنچاتے ہیں وہ قانون کے مطابق معاوضہ حاصل کرنے کا حق لطف اندوز ہوتے ہیں</td></tr><tr><td>شق ۱۱</td><td>کاروباری آپریٹرز کی بنیادی ذمہ داریاں مقرر کرتا ہے: قانونی اور معاہدہ کی ذمہ داریاں پوری کرنا، نگرانی قبول کرنا، سلامتی کی ضمانت دینا، سچی معلومات فراہم کرنا، واؤچر جاری کرنا، معیار کی ضمانت دینا، تین ضمانتیں پوری کرنا، غیر منصفانہ لین دین نہیں کرنا، شخصیت کی خلاف ورزی نہیں کرنا</td></tr><tr><td>شق ۱۲</td><td>کاروباری آپریٹرز کی سلامتی کی ضمانت کی ذمہ داری کو مقرر کرتا ہے: کاروباری آپریٹرز کو اس بات کو یقینی بنانا چاہیے کہ وہ سامان یا خدمات جو فراہم کرتے ہیں وہ ذاتی اور جائیداد کی سلامتی کے تحفظ کے تقاضوں پر پورا اترتے ہیں</td></tr><tr><td>شق ۱۳</td><td>کاروباری آپریٹرز کی معلومات کے افشا کرنے کی ذمہ داری کو مقرر کرتا ہے: کاروباری آپریٹرز کو صارفین کو سامان یا خدمات کے بارے میں سچی معلومات فراہم کرنی چاہیے، اور جھوٹی یا گمراہ کن تشہیر نہیں کرنی چاہیے</td></tr><tr><td>شق ۱۴</td><td>کھتی کے سامان اور خدمات کے لیے خصوصی معیارات مقرر کرتا ہے: کھتی کے طریقوں، کھتی کے آلات اور توانائی کے سامان کے کاروباری آپریٹرز کے پاس خصوصی قابلیت ہونی چاہیے، اور مصنوعات کو سلامتی کی سرٹیفیکیشن پاس کرنا چاہیے</td></tr><tr><td>شق ۱۵</td><td>معیاری شقوں کے ضابطے کو مقرر کرتا ہے: کاروباری آپریٹرز معیاری شقوں کے ذریعے صارفین کے حقوق کو خارج یا محدود نہیں کر سکتے، کاروباری آپریٹرز کی ذمہ داریوں کو کم یا مستثنیٰ نہیں کر سکتے</td></tr><tr><td>شق ۱۶</td><td>سات دن کی بغیر وجہ واپسی کا نظام مقرر کرتا ہے: جو صارفین انٹرنیٹ جیسے دور دراز طریقوں سے سامان خریدتے ہیں ان کے پاس سامان وصول کرنے کی تاریخ سے سات دن کے اندر سامان واپس کرنے کا حق ہے</td></tr><tr><td>شق ۱۷</td><td>تین ضمانتیں کا نظام مقرر کرتا ہے: اگر کاروباری آپریٹرز کی طرف سے فراہم کردہ سامان یا خدمات معیار کے تقاضوں پر پورا نہ اترتی ہیں، تو صارفین ریاستی ضوابط کے مطابق مرمت، تبدیلی یا واپسی کا مطالبہ کر سکتے ہیں</td></tr><tr><td>شق ۱۸</td><td>تعزیری معاوضے کا نظام مقرر کرتا ہے: اگر کاروباری آپریٹرز کی طرف سے سامان یا خدمات فراہم کرنے میں دھوکہ دہی کا رویہ ہوتا ہے، تو انہیں صارفین کے مطالبے کے مطابق صارفین کو ہونے والے نقصان کے معاوضے میں اضافہ کرنا چاہیے، اور بڑھا ہوا معاوضہ کی رقم صارفین کے ذریعے خریدے گئے سامان کی قیمت یا وصول کردہ خدمات کی لاگت کا تین گنا ہونی چاہیے</td></tr><tr><td>شق ۱۹</td><td>صارفین کی تنظیموں کو مقرر کرتا ہے: صارفین کی انجمنیں اور دیگر صارفین کی تنظیمیں قانون کے مطابق قائم کردہ سماجی تنظیمیں ہیں جو صارفین کے جائز حقوق اور مفادات کے تحفظ کے لیے سامان اور خدمات پر سماجی نگرانی کرتی ہیں</td></tr><tr><td>شق ۲۰</td><td>صارفین کے تنازعات کے حل کے چینلز کو مقرر کرتا ہے: کاروباری آپریٹرز کے ساتھ مذاکرات اور تصفیہ، صارفین کی انجمن کی ثالثی کی درخواست، متعلقہ انتظامی محکمے میں اپیل، سالوینٹی کے لیے درخواست، عدالت میں مقدمہ درج کرنا</td></tr><tr><td>شق ۲۱</td><td>تنازعات میں ثبوت کے بوجھ کی الٹ گنتی کو مقرر کرتا ہے: پائیدار سامان یا سجاوٹ جیسی خدمات کے لیے، اگر صارفین قبولیت کی تاریخ سے چھ ماہ کے اندر نقائص تلاش کرتے ہیں، تو کاروباری آپریٹر ثبوت کا بوجھ اٹھاتا ہے</td></tr><tr><td>شق ۲۲</td><td>کاروباری آپریٹرز کی انتظامی اور فوجداری ذمہ داریاں مقرر کرتا ہے</td></tr><tr><td>شق ۲۳</td><td>اس قانون کے نافذ ہونے کی تاریخ اور تشریح کے حق کو مقرر کرتا ہے</td></tr></tbody></table><h2 id="۵-پانچ-معاون-قوانین" tabindex="-1">۵. پانچ معاون قوانین <a class="header-anchor" href="#۵-پانچ-معاون-قوانین" aria-label="Permalink to &quot;۵. پانچ معاون قوانین&quot;">​</a></h2><h3 id="۵-۱-تعلیمی-تحفظ-کا-قانون" tabindex="-1">۵.۱ تعلیمی تحفظ کا قانون <a class="header-anchor" href="#۵-۱-تعلیمی-تحفظ-کا-قانون" aria-label="Permalink to &quot;۵.۱ تعلیمی تحفظ کا قانون&quot;">​</a></h3><table tabindex="0"><thead><tr><th>شق نمبر</th><th>بنیادی مواد</th></tr></thead><tbody><tr><td>شق ۱</td><td>قانون سازی کا مقصد: تمام شعور دار مخلوقات کے مساوی تعلیم کے حق کی ضمانت دینا، سمبیوسس تعلیمی نظام کی تعمیر کرنا، اور تمام نسلوں کی ثقافتوں کے مشترکہ ترقی کو فروغ دینا</td></tr><tr><td>شق ۲-۵</td><td>تعلیمی مساوات کے اصول، مفت تعلیم کے اصول (بنیادی تعلیم کے مرحلے)، تعلیمی تنوع کے اصول، تعلیمی جدت کے اصول قائم کرتا ہے</td></tr><tr><td>شق ۶-۱۰</td><td>پری اسکول تعلیم، لازمی تعلیم، ہائی اسکول تعلیم، ہائر تعلیم، کھتی کی تعلیم کے نظام کی معماریت مقرر کرتا ہے</td></tr><tr><td>شق ۱۱-۱۵</td><td>کھتی کی تعلیم کے لیے خصوصی نظام مقرر کرتا ہے: تین سو سیٹ نظاموں کی تدریس کے معیارات، سرپرستوں کا نظام، کھتی کے وسائل کی مختصات کا نظام</td></tr><tr><td>شق ۱۶-۲۰</td><td>اساتذہ کے حقوق اور ذمہ داریاں، اساتذہ کی قابلیت کا نظام، اساتذہ کے سلوک کی ضمانت مقرر کرتا ہے</td></tr><tr><td>شق ۲۱-۲۵</td><td>تعلیمی سرمایہ کاری کی ضمانت، تعلیمی سہولیات کی تعمیر، تعلیمی انفارمیشن ٹیکنالوجی، خاص تعلیم، بین نسلی تعلیم مقرر کرتا ہے</td></tr><tr><td>شق ۲۶-۳۰</td><td>تعلیمی تشخیص کا نظام، تعلیمی نگرانی کا نظام، قانونی ذمہ داریاں اور ضمنی دفعات مقرر کرتا ہے</td></tr></tbody></table><h3 id="۵-۲-طبی-تحفظ-کا-قانون" tabindex="-1">۵.۲ طبی تحفظ کا قانون <a class="header-anchor" href="#۵-۲-طبی-تحفظ-کا-قانون" aria-label="Permalink to &quot;۵.۲ طبی تحفظ کا قانون&quot;">​</a></h3><table tabindex="0"><thead><tr><th>شق نمبر</th><th>بنیادی مواد</th></tr></thead><tbody><tr><td>شق ۱</td><td>قانون سازی کا مقصد: عالمگیر طبی تحفظ کا نظام قائم کرنا، تمام شعور دار مخلوقات کے صحت کے حق کی ضمانت دینا، اور تمام نسلوں کی مجموعی صحت کی سطح کو بہتر بنانا</td></tr><tr><td>شق ۲-۵</td><td>عالمگیر طبی بیمے کے اصول، بنیادی طبی مفت کے اصول، چینی اور مغربی ادویات کے انضمام کے اصول، کھتی کی ادویات کے شمولیت کے اصول قائم کرتا ہے</td></tr><tr><td>شق ۶-۱۰</td><td>بنیادی طبی بیمہ، سنگین بیماریوں کا بیمہ، طبی امداد، تجارتی صحت کے بیمے کے کثیر سطحی طبی بیمے کا نظام مقرر کرتا ہے</td></tr><tr><td>شق ۱۱-۱۵</td><td>طبی اداروں کا انتظام، طبی عملے کا نظام، طبی معیار اور سلامتی، کھتی کی ادویات کے لیے خصوصی معیارات مقرر کرتا ہے</td></tr><tr><td>شق ۱۶-۲۰</td><td>ادویات کا انتظام، طبی آلات کا انتظام، توانائی کی طبی مصنوعات کا انتظام، ضروری ادویات کا نظام مقرر کرتا ہے</td></tr><tr><td>شق ۲۱-۲۵</td><td>صحت عامہ کا نظام، بیماریوں کی روک تھام اور کنٹرول، صحت کی تعلیم، بین نسلی ادویات، خاص گروہوں کی طبی تحفظ مقرر کرتا ہے</td></tr><tr><td>شق ۲۶-۳۰</td><td>طبی تنازعات کا حل، طبی نگرانی، قانونی ذمہ داریاں اور ضمنی دفعات مقرر کرتا ہے</td></tr></tbody></table><h3 id="۵-۳-رہائشی-تحفظ-کا-قانون" tabindex="-1">۵.۳ رہائشی تحفظ کا قانون <a class="header-anchor" href="#۵-۳-رہائشی-تحفظ-کا-قانون" aria-label="Permalink to &quot;۵.۳ رہائشی تحفظ کا قانون&quot;">​</a></h3><table tabindex="0"><thead><tr><th>شق نمبر</th><th>بنیادی مواد</th></tr></thead><tbody><tr><td>شق ۱</td><td>قانون سازی کا مقصد: تمام شعور دار مخلوقات کے بنیادی رہائش کے حق کی ضمانت دینا، کثیر سطحی رہائشی تحفظ کا نظام کی تعمیر کرنا، اور سب کے لیے رہائش حاصل کرنا</td></tr><tr><td>شق ۲-۵</td><td>رہائش کے حق کے تحفظ کا اصول، رہائشی مساوات کا اصول، کرایہ اور خریداری یکجا کے اصول، پائیدار رہائش کے اصول قائم کرتا ہے</td></tr><tr><td>شق ۶-۱۰</td><td>عوامی کرایہ رہائش، سستی کرایہ رہائش، مشترکہ ملکیت رہائش، تجارتی رہائش کے رہائش کی فراہمی کا نظام مقرر کرتا ہے</td></tr><tr><td>شق ۱۱-۱۵</td><td>رہائشی پروویڈنٹ فنڈ کا نظام، رہائشی سبسڈی کا نظام، پہلی رہائش کی معاونت کی پالیسی، کھتیوں کے لیے خصوصی رہائشی پالیسی مقرر کرتا ہے</td></tr><tr><td>شق ۱۶-۲۰</td><td>رہائش کی تعمیر کے معیارات، رہائش میں خلائی ٹیکنالوجی کا اطلاق، سبز عمارتیں، بزرگوں کے لیے موزوں اور بغیر رکاوٹ رہائش مقرر کرتا ہے</td></tr><tr><td>شق ۲۱-۲۵</td><td>رئیل اسٹیٹ مارکیٹ کا ضابطہ، رہائشی کرایہ مارکیٹ کا ضابطہ، پراپرٹی سروسز کا انتظام، رہائش کی دیکھ بھال کی ضمانت مقرر کرتا ہے</td></tr><tr><td>شق ۲۶-۳۰</td><td>رہائشی تحفظ کی نگرانی، قانونی ذمہ داریاں اور ضمنی دفعات مقرر کرتا ہے</td></tr></tbody></table><h3 id="۵-۴-ماحولیات-کے-تحفظ-کا-قانون" tabindex="-1">۵.۴ ماحولیات کے تحفظ کا قانون <a class="header-anchor" href="#۵-۴-ماحولیات-کے-تحفظ-کا-قانون" aria-label="Permalink to &quot;۵.۴ ماحولیات کے تحفظ کا قانون&quot;">​</a></h3><table tabindex="0"><thead><tr><th>شق نمبر</th><th>بنیادی مواد</th></tr></thead><tbody><tr><td>شق ۱</td><td>قانون سازی کا مقصد: ماحولیات کی حفاظت اور بہتری، آلودگی اور دیگر عوامی نقصانات کی روک تھام اور کنٹرول، عوامی صحت کی ضمانت، کائناتی ماحولیاتی تہذیب کی تعمیر کو فروغ دینا، اور پائیدار ترقی کو فروغ دینا</td></tr><tr><td>شق ۲-۵</td><td>تحفظ کی ترجیح کے اصول، روک تھام کو پہلے کے اصول، جامع انتظام کے اصول، عوامی شرکت کے اصول، نقصان کی ذمہ داری کے اصول قائم کرتا ہے</td></tr><tr><td>شق ۶-۱۰</td><td>ماحولیاتی نگرانی اور انتظام کا نظام، ماحولیاتی معیارات کا نظام، ماحولیاتی اثرات کی تشخیص کا نظام، ماحولیاتی نگرانی کا نظام، بین طیارہ ماحولیاتی انتظام مقرر کرتا ہے</td></tr><tr><td>شق ۱۱-۱۵</td><td>فضائی آلودگی کی روک تھام اور کنٹرول، پانی کی آلودگی کی روک تھام اور کنٹرول، مٹی کی آلودگی کی روک تھام اور کنٹرول، توانائی کی آلودگی کی روک تھام اور کنٹرول، قانون کی آلودگی کی روک تھام اور کنٹرول مقرر کرتا ہے</td></tr><tr><td>شق ۱۶-۲۰</td><td>ٹھوس فضلہ کا انتظام، صوتی آلودگی کی روک تھام اور کنٹرول، تابکار آلودگی کی روک تھام اور کنٹرول، ماحولیاتی تحفظ، حیاتیاتی تنوع کا تحفظ مقرر کرتا ہے</td></tr><tr><td>شق ۲۱-۲۵</td><td>کھتی کی سرگرمیوں کے ماحولیاتی اثرات کا کنٹرول، توانائی کی کان کنی کے ماحولیاتی تحفظ، بین طیارہ آثار قدیمہ کے لیے ماحولیاتی تقاضے مقرر کرتا ہے</td></tr><tr><td>شق ۲۶-۳۰</td><td>معلومات کے افشا کرنے اور عوامی شرکت، ماحولیاتی عوامی مفاد کے مقدمے، قانونی ذمہ داریاں اور ضمنی دفعات مقرر کرتا ہے</td></tr></tbody></table><h3 id="۵-۵-یکجا-فروشی-کے-خلاف-قانون" tabindex="-1">۵.۵ یکجا فروشی کے خلاف قانون <a class="header-anchor" href="#۵-۵-یکجا-فروشی-کے-خلاف-قانون" aria-label="Permalink to &quot;۵.۵ یکجا فروشی کے خلاف قانون&quot;">​</a></h3><table tabindex="0"><thead><tr><th>شق نمبر</th><th>بنیادی مواد</th></tr></thead><tbody><tr><td>شق ۱</td><td>قانون سازی کا مقصد: یکجا فروشی کے رویے کو روکنا اور روکنا، مارکیٹ کے منصفانہ مسابقت کا تحفظ کرنا، معاشی آپریشن کی کارکردگی کو بہتر بنانا، صارفین کے مفادات اور سماجی عوامی مفاد کی حفاظت کرنا، اور سمبیوسس مارکیٹ معیشت کی صحت مند ترقی کو فروغ دینا</td></tr><tr><td>شق ۲-۵</td><td>مسابقت کی پالیسی کی بنیادی پوزیشن، منصفانہ مسابقت کی نظرثانی کا نظام، یکجا فروشی کے معاہدوں کی ممانعت، مارکیٹ میں غالب پوزیشن کے غلط استعمال کی ممانعت، کاروباری آپریٹرز کے ارتکاز کا کنٹرول قائم کرتا ہے</td></tr><tr><td>شق ۶-۱۰</td><td>یکجا فروشی کے معاہدوں کی شناخت اور چھٹی، افقی یکجا فروشی کے معاہدے، عمودی یکجا فروشی کے معاہدے، صنعتی انجمنوں کے یکجا فروشی کے رویے مقرر کرتا ہے</td></tr><tr><td>شق ۱۱-۱۵</td><td>مارکیٹ میں غالب پوزیشن کی شناخت، مارکیٹ میں غالب پوزیشن کے غلط استعمال کے رویے کی اقسام، شکاری قیمتوں کی ممانعت مقرر کرتا ہے</td></tr><tr><td>شق ۱۶-۲۰</td><td>کاروباری آپریٹرز کے ارتکاز کے اعلان کے معیارات، نظرثانی کے طریقہ کار، اضافی پابندی والی شرائط، ارتکاز کی ممانعت کے فیصلے مقرر کرتا ہے</td></tr><tr><td>شق ۲۱-۲۵</td><td>کھتی کے نظام کی یکجا فروشی کی خاص ممانعت مقرر کرتا ہے: کھتی کے طریقوں کو یکجا کرنے کی ممانعت، کھتی کے وسائل کی یکجا فروشی کی ممانعت، سرپرستوں کے نیٹ ورک کی یکجا فروشی کی ممانعت</td></tr><tr><td>شق ۲۶-۳۰</td><td>یکجا فروشی کے خلاف قانون نافذ کرنے والی ایجنسیاں، تحقیقات کے طریقہ کار، قانونی ذمہ داریاں، معافی کا نظام اور ضمنی دفعات مقرر کرتا ہے</td></tr></tbody></table><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>قانونی شقوں کا اشاریہ اینکر سمبیوسس تہذیب کے قانون کی حکومت کے نظام کا ایک حوالہ جاتی نقشہ ہے۔ بنیادی قانون کے طور پر سمبیوسس آئین سے شروع کرتے ہوئے، لوگوں کی زندگی کو منظم کرنے والے محنت قانون اور صارفین کے تحفظ کے قانون تک، اور پھر پانچ معاون قوانین تک، وہ مل کر &quot;آئین کو کمانڈر کے طور پر، بنیادی قوانین کو ریڑھ کی ہڈی کے طور پر، اور معاون قوانین کو مدد کے طور پر&quot; ایک مکمل قانونی نظام تشکیل دیتے ہیں۔ یہ نظام اس بات کو یقینی بناتا ہے کہ سمبیوسس تہذیب کی تمام سرگرمیاں قانون کی حکومت کے راستے پر چلتی ہیں، تمام نسلوں کی مشترکہ ترقی کے لیے ایک مضبوط ادارتی ضمانت فراہم کرتی ہیں۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>40-سمبیوسس آئین کا عمومی خاکہ</li><li>41-سمبیوسس محنت قانون</li><li>48-عدالتی نظام اور فیصلے کا طریقہ کار</li></ul>',28)])])}const c=d(h,[["render",o]]);export{q as __pageData,c as default};
